class Solution {
public:
    int idealArrays(int n, int maxValue) {
        long long MOD = 1e9 + 7;
        int max_len = std::min(n, 14);
        std::vector<std::vector<long long>> dp(max_len + 1, std::vector<long long>(maxValue + 1, 0));
        for (int v = 1; v <= maxValue; ++v) dp[1][v] = 1;
        for (int l = 1; l < max_len; ++l) {
            for (int v = 1; v <= maxValue; ++v) {
                if (dp[l][v] == 0) continue;
                long long cnt = dp[l][v];
                for (int mul = 2 * v; mul <= maxValue; mul += v) {
                    dp[l + 1][mul] = (dp[l + 1][mul] + cnt) % MOD;
                }
            }
        }
        auto comb = [&](int N, int K) -> long long {
            if (K < 0 || K > N) return 0;
            long long num = 1, den = 1;
            for (int i = 1; i <= K; ++i) {
                num = (num * (N - i + 1)) % MOD;
                den = (den * i) % MOD;
            }
            auto power = [&](long long base, long long exp) {
                long long res = 1;
                base %= MOD;
                while (exp > 0) {
                    if (exp % 2 == 1) res = (res * base) % MOD;
                    base = (base * base) % MOD;
                    exp /= 2;
                }
                return res;
            };
            return (num * power(den, MOD - 2)) % MOD;
        };
        long long ans = 0;
        for (int l = 1; l <= max_len; ++l) {
            long long total = 0;
            for (int v = 1; v <= maxValue; ++v) total = (total + dp[l][v]) % MOD;
            ans = (ans + total * comb(n - 1, l - 1)) % MOD;
        }
        return ans;
    }
};

