                }
            }
        }
        long ans = 0;
        for (int l = 1; l <= maxLen; ++l) {
            long total = 0;
            for (int v = 1; v <= maxValue; ++v) total = (total + dp[l][v]) % MOD;
            ans = (ans + total * comb(n - 1, l - 1)) % MOD;
        }
        return (int) ans;
    }
    private long comb(int N, int K) {
        if (K < 0 || K > N) return 0;
        long num = 1, den = 1;
        for (int i = 1; i <= K; ++i) {
            num = (num * (N - i + 1)) % MOD;
            den = (den * i) % MOD;
        }
        return (num * power(den, MOD - 2)) % MOD;
    }
    private long power(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
