var idealArrays = function(n, maxValue) {
    const MOD = 1000000007n;
    const maxLen = Math.min(n, 14);
    const dp = Array.from({ length: maxLen + 1 }, () => new Array(maxValue + 1).fill(0n));
    for (let v = 1; v <= maxValue; ++v) dp[1][v] = 1n;
    for (let l = 1; l < maxLen; ++l) {
        for (let v = 1; v <= maxValue; ++v) {
            if (dp[l][v] === 0n) continue;
            const cnt = dp[l][v];
            for (let mul = 2 * v; mul <= maxValue; mul += v) {
                dp[l + 1][mul] = (dp[l + 1][mul] + cnt) % MOD;
            }
        }
    }
    function power(base, exp) {
        let res = 1n;
        base %= MOD;
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    }
    function comb(N, K) {
        if (K < 0 || K > N) return 0n;
        let num = 1n, den = 1n;
        for (let i = 1; i <= K; ++i) {
            num = (num * BigInt(N - i + 1)) % MOD;
            den = (den * BigInt(i)) % MOD;
        }
        return (num * power(den, MOD - 2n)) % MOD;
    }
    let ans = 0n;
    for (let l = 1; l <= maxLen; ++l) {
        let total = 0n;
        for (let v = 1; v <= maxValue; ++v) total = (total + dp[l][v]) % MOD;
        ans = (ans + total * comb(n - 1, l - 1)) % MOD;
    }
    return Number(ans);
};
